return fileUpload(payload).then(
  ({ data }) => {
    const mediaUrl = resolveMediaUrl(data.fileSite);
    fileList.value.push({ ...tempFiles[0], url: mediaUrl });
    // uni-file-picker 在 @select 时先把本地 blob 项塞进内部 files 作缩略图；
    // 外部 fileList 更新经 async setValue 同步，存在时序差。nextTick 后按 uuid
    // 精确定位内部项并改为服务端水印图，确保缩略图直接显示带水印图。
    if (props.cameraWatermark && savedUuid !== undefined) {
      nextTick(() => {
        const files = pickerRef.value && pickerRef.value.files;
        if (!Array.isArray(files)) return;
        const idx = files.findIndex((f) => f.uuid === savedUuid);
        if (idx === -1) return;
        files[idx].url = mediaUrl;
        files[idx].path = mediaUrl;
        if (pickerRef.value.$forceUpdate) pickerRef.value.$forceUpdate();
      });
    }

tool_input.new_string:
return fileUpload(payload).then(
  ({ data }) => {
    const mediaUrl = resolveMediaUrl(data.fileSite);
    const thumbUrl =
      props.cameraWatermark && payload.previewDataUrl
        ? payload.previewDataUrl
        : mediaUrl;
    fileList.value.push({ ...tempFiles[0], url: thumbUrl });
    // uni-file-picker 在 @select 时先把本地 blob 项塞进内部 files 作缩略图；
    // 外部 fileList 更新经 async setValue 同步，存在时序差。nextTick 后按 uuid
    // 精确定位内部项；H5 用合成 dataURL 回显水印，避免占位图。
    if (props.cameraWatermark && savedUuid !== undefined) {
      nextTick(() => {
        const files = pickerRef.value && pickerRef.value.files;
        if (!Array.isArray(files)) return;
        const idx = files.findIndex((f) => f.uuid === savedUuid);
        if (idx === -1) return;
        files[idx].url = thumbUrl;
        files[idx].path = thumbUrl;
        if (pickerRef.value.$forceUpdate) pickerRef.value.$forceUpdate();
      });
    }

